1	#!/bin/bash
2	
3	# --- Configuration ---
4	HASHI_SRC="../veashi-contracts/lib/hashi/packages/evm/contracts"
5	VEASHI_SRC="../veashi-contracts/src/adapters"
6	ARTIFACTS_DIR="../veashi-contracts/out"
7	
8	TARGET_DIR="./contracts"
9	SDK_ABI_DIR="./abi"
10	TYPECHAIN_DIR="./typechain-types"
11	
12	BROADCAST_SRC="../veashi-contracts/broadcast"
13	SDK_ADD_DIR="./addresses"
14	REGISTRY_FILE="./registry.ts"
15	
16	# --- Setup ---
17	rm -rf "$TARGET_DIR" "$SDK_ABI_DIR" "$TYPECHAIN_DIR" "$SDK_ADD_DIR"
18	mkdir -p "$TARGET_DIR" "$SDK_ABI_DIR" "$TYPECHAIN_DIR" "$SDK_ADD_DIR"
19	
20	echo "🎯 Executing targeted copy and dependency crawl..."
21	
22	node -e "
23	const fs = require('fs');
24	const path = require('path');
25	
26	const collectedFiles = new Set();
27	
28	/**
29	 * CORE LOGIC: 
30	 * We define exactly what we want and where it goes.
31	 */
32	const COPY_PLAN = [
33	    // HASHI CORE -> Target Root
34	    { srcBase: '$HASHI_SRC', file: 'Hashi.sol', destSubDir: '' },
35	    { srcBase: '$HASHI_SRC', file: 'Yaho.sol', destSubDir: '' },
36	    { srcBase: '$HASHI_SRC', file: 'Yaru.sol', destSubDir: '' },
37	
38	    // HASHI ADAPTERS -> adapters/layerZero/
39	    { srcBase: '$HASHI_SRC', file: 'adapters/layerZero/LayerZeroAdapter.sol', destSubDir: 'adapters/layerZero' },
40	    { srcBase: '$HASHI_SRC', file: 'adapters/layerZero/LayerZeroReporter.sol', destSubDir: 'adapters/layerZero' },
41	
42	    // VEASHI SRC -> adapters/ (Vea, DeBridge, Chainlink and Axelar)
43	    { srcBase: '$VEASHI_SRC', file: 'vea', destSubDir: 'adapters/vea' },
44	    { srcBase: '$VEASHI_SRC', file: 'chainlink', destSubDir: 'adapters/chainlink' },
45	    { srcBase: '$VEASHI_SRC', file: 'deBridge', destSubDir: 'adapters/deBridge' },
46	    { srcBase: '$VEASHI_SRC', file: 'axelar', destSubDir: 'adapters/axelar' }
47	];
48	
49	/**
50	 * Dependency Crawler
51	 * Ensures that if a contract is moved, its internal imports (interfaces/utils) follow it.
52	 */
53	function processPath(baseDir, relativePath, targetSubDir) {
54	    const fullPath = path.resolve(baseDir, relativePath);
55	    if (!fs.existsSync(fullPath) || collectedFiles.has(fullPath)) return;
56	
57	    const stats = fs.statSync(fullPath);
58	
59	    if (stats.isDirectory()) {
60	        fs.readdirSync(fullPath).forEach(file => {
61	            processPath(baseDir, path.join(relativePath, file), targetSubDir);
62	        });
63	        return;
64	    }
65	
66	    // Only process .sol files
67	    if (!relativePath.endsWith('.sol')) return;
68	
69	    collectedFiles.add(fullPath);
70	    
71	    // Construct the destination: TARGET_DIR + specific subDir + the filename
72	    const fileName = path.basename(fullPath);
73	    const finalDest = path.join('$TARGET_DIR', targetSubDir, fileName);
74	
75	    fs.mkdirSync(path.dirname(finalDest), { recursive: true });
76	    fs.copyFileSync(fullPath, finalDest);
77	    console.log('✅ Copied: ' + fileName + ' -> ' + targetSubDir);
78	
79	    // Crawl Imports
80	    const content = fs.readFileSync(fullPath, 'utf8');
81	    const importRegex = /import\s+(?:\{.*\}\s+from\s+)?['\"](.*\.sol)['\"]/g;
82	    let match;
83	
84	    while ((match = importRegex.exec(content)) !== null) {
85	        const importPath = match[1];
86	        // Resolve relative to the current file's directory within its original source
87	        const resolvedImport = path.join(path.dirname(relativePath), importPath);
88	        
89	        // Dependencies maintain their internal relative structure (e.g. ./interfaces/...)
90	        // unless they are part of the core files we already moved.
91	        const depTargetSubDir = path.join(targetSubDir, path.dirname(importPath));
92	        processPath(baseDir, resolvedImport, depTargetSubDir);
93	    }
94	}
95	
96	// Execute the plan
97	COPY_PLAN.forEach(plan => {
98	    console.log('--- Processing: ' + plan.file + ' ---');
99	    processPath(plan.srcBase, plan.file, plan.destSubDir);
100	});
101	"
102	
103	# --- ABI Extraction (Stays the same) ---
104	echo "📑 Extracting ABIs..."
105	node -e "
106	const fs = require('fs');
107	const path = require('path');
108	const ALLOW = [
109	  'Hashi.json', 'Yaho.json', 'Yaru.json', 
110	  'LayerZeroAdapter.json', 'LayerZeroReporter.json',
111	  'VeaAdapter.json', 'VeaReporter.json',
112	  'CCIPAdapter.json', 'CCIPReporter.json','Reporter.json',
113	  'Adapter.json', 'DeBridgeReporter.json', 'DeBridgeAdapter.json',
114	  'AxelarReporter.json', 'AxelarAdapter.json'
115	];
116	function walk(dir) {
117	    if(!fs.existsSync(dir)) return;
118	    fs.readdirSync(dir).forEach(f => {
119	        const p = path.join(dir, f);
120	        if (fs.statSync(p).isDirectory()) walk(p);
121	        else if (ALLOW.includes(f)) {
122	            const c = JSON.parse(fs.readFileSync(p, 'utf8'));
123	            if (c.abi) fs.writeFileSync(path.join('$SDK_ABI_DIR', f), JSON.stringify(c.abi, null, 2));
124	        }
125	    });
126	}
127	walk('$ARTIFACTS_DIR');
128	"
129	
130	# Run TypeChain ONLY on the filtered ABIs
131	echo "🚀 Generating targeted TypeChain types..."
132	npx typechain --target ethers-v6 "$SDK_ABI_DIR/*.json" --out-dir "$TYPECHAIN_DIR"
133	
134	# Syncing Addresses with SDK
135	echo "🔗 Syncing chain-specific broadcast files to SDK..."
136	
137	node -e "
138	const fs = require('fs');
139	const path = require('path');
140	
141	const broadcastDir = '$BROADCAST_SRC';
142	const destDir = '$SDK_ADD_DIR';
143	
144	// Regex to match files like 1-137.json or 42161-10.json
145	const chainPairRegex = /^\d+-\d+\.json$/;
146	
147	function syncChainFiles(dir) {
148	    if (!fs.existsSync(dir)) return;
149	
150	    fs.readdirSync(dir).forEach(file => {
151	        const fullPath = path.join(dir, file);
152	        const stats = fs.statSync(fullPath);
153	
154	        if (stats.isDirectory()) {
155	            syncChainFiles(fullPath);
156	        } else if (chainPairRegex.test(file)) {
157	            const destFile = path.join(destDir, file);
158	            fs.copyFileSync(fullPath, destFile);
159	            console.log('✅ Synced: ' + file + ' -> ' + destDir);
160	        }
161	    });
162	}
163	
164	syncChainFiles(broadcastDir);
165	"
166	
167	# Regenerating the SDK route registry from the synced address files
168	echo "📝 Regenerating registry.ts from synced addresses..."
169	
170	node -e "
171	const fs = require('fs');
172	
173	const addrDir = '$SDK_ADD_DIR';
174	const registryFile = '$REGISTRY_FILE';
175	const chainPairRegex = /^\d+-\d+\.json$/;
176	
177	const routes = fs.readdirSync(addrDir).filter(f => chainPairRegex.test(f)).sort();
178	
179	const lines = [];
180	lines.push('import type { FlatRouteFile } from ' + JSON.stringify('./types') + ';');
181	lines.push('');
182	routes.forEach((f, i) => {
183	    lines.push('import route_' + i + ' from ' + JSON.stringify('./addresses/' + f) + ';');
184	});
185	lines.push('');
186	lines.push('export const ROUTES: Record<string, FlatRouteFile> = {');
187	routes.forEach((f, i) => {
188	    lines.push('  ' + JSON.stringify(f.replace(/\.json$/, '')) + ': route_' + i + ',');
189	});
190	lines.push('};');
191	lines.push('');
192	
193	fs.writeFileSync(registryFile, lines.join('\n'));
194	console.log('✅ Registry updated with ' + routes.length + ' route(s)');
195	"
196	
197	echo "✨ Done! Your target directory is now structured correctly."

